{
  "name": "skill-author",
  "version": "1.1.0",
  "description": "A meta-skill for creating, validating, and publishing Agent Skills that work across Claude Code, Codex, Pi, OpenCode, GitHub Copilot, and other harnesses.",
  "keywords": [
    "skill",
    "ai",
    "agent",
    "claude",
    "openai",
    "copilot",
    "llm",
    "skills",
    "pi-package",
    "pi",
    "opencode",
    "agent-skills"
  ],
  "homepage": "https://github.com/vijayet1/skill-author#readme",
  "bugs": {
    "url": "https://github.com/vijayet1/skill-author/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/vijayet1/skill-author.git"
  },
  "license": "MIT",
  "author": "vijayet1",
  "main": "index.js",
  "bin": {
    "skill-author": "./bin/install.js"
  },
  "files": [
    "bin/",
    "lib/",
    "skills/",
    "scripts/",
    "AGENTS.md",
    "index.js"
  ],
  "pi": {
    "skills": [
      "./skills"
    ]
  },
  "scripts": {
    "install-skill": "node bin/install.js",
    "validate": "node scripts/validate.js",
    "test": "node --test",
    "version": "node scripts/sync-version.js && git add .claude-plugin/plugin.json",
    "prepublishOnly": "npm run validate && npm test"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "publishConfig": {
    "access": "public"
  }
}
